}
section.lead h2 strong {
  -webkit-text-stroke: 1px #800000;
}
section.lead h3 {
  color: #800000;
  text-align: left;
}
section.lead h3 strong {
  -webkit-text-stroke: 1px #800000;
}
section.lead h4 {
  color: #800000;
  text-align: left;
}
section.lead h4 strong {
  -webkit-text-stroke: 1px #800000;
}
section.lead h5 {
  color: #800000;
  text-align: left;
}
section.lead h5 strong {
  -webkit-text-stroke: 1px #800000;
}
section.lead p {
  text-align: right;
}

header {
  background-color: #800000;
  color: #fff;
  font-size: 1em;
  font-weight: 700;
}

blockquote {
  max-width: 90%;
  border-top: 0.1em dashed #555;
  font-size: 60%;
  position: absolute;
  bottom: 20px;
}
blockquote::before {
  content: "";
}
blockquote::after {
  content: "";
}

img[alt~="center"] {
  display: block;
  margin: 0 auto;
}

code {
  font-family: 'Source Code Pro', monospace;
